fn open_spine(&mut self, t: Type) -> Type {
    match t {
        Type::Fun(a, b, mut e) => {
            if e.tail.is_none() {
                e.tail = Some(self.env.table.fresh(Kind::Eff, self.level));
            }
            let b = self.open_spine(*b);
            Type::Fun(a, Box::new(b), e)
        }
        other => other,
    }
}
